13|  --line-2:#A8A497;     /* the path */
14|  --green:#2C6A53;      /* mineral green: the one active colour */
15|  --green-t:#DCE7DF;
16|  --amber:#B06E14;      /* human approval only */
17|  --amber-ink:#83500A;
18|  --amber-t:#F5E6CC;
19|  --sans:"Inter Tight",ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;
20|  --mono:"Geist Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
21|  --serif:"IBM Plex Serif",Georgia,serif;
22|  --nav:68px;
23|  --gut:clamp(20px,4vw,56px);
24|  --max:1360px;
25|  --ease:cubic-bezier(.2,.7,.2,1);
26|}
27|*,*::before,*::after{box-sizing:border-box}
28|html{-webkit-text-size-adjust:100%;text-size-adjust:100%;scroll-padding-top:calc(var(--nav) + 16px)}
29|body{margin:0;background:var(--ivory);color:var(--ink);font-family:var(--sans);font-size:clamp(17px,1.05vw + 12px,19px);line-height:1.55;
30|  font-feature-settings:"ss01","cv11";-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility;overflow-x:clip}
31|img,svg{display:block;max-width:100%}
32|a{color:inherit;text-underline-offset:.2em;text-decoration-thickness:1px}
33|a:hover{text-decoration-color:var(--green)}
34|h1,h2,h3,h4{margin:0;font-weight:500;letter-spacing:-.03em;line-height:1.02;text-wrap:balance}
