45|/* type scale */
46|.eyebrow{font-family:var(--mono);font-size:14px;letter-spacing:.06em;text-transform:uppercase;color:var(--ink-2);display:flex;align-items:center;gap:10px}
47|.eyebrow::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--green);flex:none}
48|.d1{font-size:clamp(46px,7.4vw,116px);letter-spacing:-.045em;line-height:.96}
49|.d2{font-size:clamp(36px,4.9vw,76px);letter-spacing:-.04em;line-height:1}
50|.d3{font-size:clamp(28px,2.9vw,46px);letter-spacing:-.03em;line-height:1.06}
51|.lede{font-size:clamp(19px,1.35vw + 11px,24px);line-height:1.45;color:var(--ink-2);max-width:34em}
52|.muted{color:var(--ink-2)}
53|.mono{font-family:var(--mono)}
