55|/* buttons */
56|.btn{display:inline-flex;align-items:center;justify-content:center;gap:12px;min-height:54px;padding:0 26px;border-radius:999px;border:1.5px solid var(--ink);
57|  font-size:17px;font-weight:500;letter-spacing:-.01em;text-decoration:none;cursor:pointer;transition:background .2s,color .2s,transform .2s var(--ease)}
58|.btn-ink{background:var(--ink);color:var(--ivory)}
