2|import { AbsoluteFill, Easing, interpolate, useCurrentFrame, useVideoConfig } from "remotion";
3|import { loadFont as loadSans } from "@remotion/google-fonts/InterTight";
4|import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
