6|/* Twinthos · 15-second showreel. Why → product → benefits → promise.
7|   Tokens mirror the live twinthos.com dark surfaces. */
8|const sans = loadSans("normal", { weights: ["400", "500", "600"], subsets: ["latin"], ignoreTooManyRequestsWarning: true });
9|const mono = loadMono("normal", { weights: ["400"], subsets: ["latin"], ignoreTooManyRequestsWarning: true });
10|
11|const C = {
12|  bg: "#0E100E", ink: "#F4F0E6", ink2: "#CAC6BA", mute: "rgba(244,240,230,.46)",
13|  line: "rgba(244,240,230,.16)", green: "#6CC79A", amber: "#E6A54D",
14|  sans: `${sans.fontFamily}, sans-serif`, mono: `${mono.fontFamily}, monospace`,
15|};
16|const E = Easing.bezier(0.2, 0.7, 0.1, 1);
17|const EIO = Easing.bezier(0.65, 0, 0.25, 1);
18|const ip = (t: number, a: number, b: number, c: number, d: number, e = E) =>
19|  interpolate(t, [a, b], [c, d], { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: e });
20|const win = (t: number, a: number, b: number, fi = 0.35, fo = 0.3) =>
21|  Math.min(ip(t, a, a + fi, 0, 1), 1 - ip(t, b - fo, b, 0, 1));
22|
23|const MarkPath = "M11 12H30.75V52H26V20H11ZM33.25 12H53V20H38V52H33.25Z";
24|const Mark: React.FC<{ size: number; color?: string }> = ({ size, color = C.ink }) => (
25|  <svg width={size} height={size} viewBox="8 8 48 48"><path d={MarkPath} fill={color} /></svg>
26|);
27|
28|/* masked line reveal: text rises out of a slot */
29|const Rise: React.FC<{ t: number; at: number; out?: number; children: React.ReactNode; style?: React.CSSProperties; dur?: number }> =
30|  ({ t, at, out = 99, children, style, dur = 0.7 }) => {
31|    const y = ip(t, at, at + dur, 105, 0) + ip(t, out, out + 0.45, 0, -105, EIO);
32|    return (
33|      <div style={{ overflow: "hidden", paddingBottom: "0.12em", marginBottom: "-0.12em" }}>
34|        <div style={{ transform: `translateY(${y}%)`, ...style }}>{children}</div>
35|      </div>
36|    );
37|  };
38|
39|const TASKS = ["Reply to the enquiry", "Chase the details", "Update the record", "Send the follow-up"];
40|const STATION_LAB = ["Read the enquiry", "Ask for the details", "Update the record", "Send the follow-up"];
41|const STEPS = [
42|  { at: 5.0, ts: "10:42", txt: "Enquiry read." },
43|  { at: 5.85, ts: "10:42", txt: "Details requested." },
44|  { at: 6.85, ts: "10:43", txt: "Record updated." },
45|  { at: 7.85, ts: "10:43", txt: "Follow-up scheduled." },
46|  { at: 8.75, ts: "10:44 · 15% discount?", txt: "Your team decides.", amber: true },
47|];
48|const SCENES = [
49|  [0, 2.9, "01", "The problem"], [2.9, 4.8, "02", "Twinthos"], [4.8, 9.85, "03", "How it works"],
50|  [9.85, 12.8, "04", "What you get"], [12.8, 15, "05", "The promise"],
51|] as const;
