53|export const Show15: React.FC = () => {
54|  const f = useCurrentFrame();
55|  const { fps, width: W, height: H } = useVideoConfig();
56|  const t = f / fps;
57|  const P = H > W; // portrait cut
58|  const u = Math.min(W, H) / 1080; // unit scale
59|  const cx = W / 2, cy = P ? H * 0.47 : H / 2;
60|  const R = (P ? 215 : 300) * u;
61|  const labF = (P ? 20 : 22) * u;
62|  const pt = (deg: number, r = R) => [cx + r * Math.sin((deg * Math.PI) / 180), cy - r * Math.cos((deg * Math.PI) / 180)];
63|
64|  /* ── marker angle along the ring ── */
65|  const ang =
66|    t < 5.25 ? 0 :
67|    t < 6.25 ? ip(t, 5.25, 5.85, 0, 90, EIO) :
68|    t < 7.25 ? ip(t, 6.25, 6.85, 90, 180, EIO) :
69|    t < 8.25 ? ip(t, 7.25, 7.85, 180, 270, EIO) :
70|    t < 9.9 ? ip(t, 8.25, 8.75, 270, 315, EIO) :
71|    ip(t, 9.9, 10.6, 315, 360, EIO);
72|  const arrivals = [5.0, 5.85, 6.85, 7.85];
73|  const decided = t >= 8.75 && t < 9.9;
74|
75|  /* ── scene-level camera ── */
76|  const push = 1 + 0.035 * ip(t, 0, 15, 0, 1, Easing.linear);
77|  const s4 = ip(t, 9.75, 10.55, 0, 1, EIO);
78|  const gScale = 1 - (P ? 0.2 : 0.24) * s4;
79|  const gdx = P ? 0 : -430 * u * s4, gdy = P ? -230 * u * s4 : 0;
80|  const gOut = 1 - ip(t, 12.65, 13.15, 0, 1);
81|  const finalFade = 1 - ip(t, 14.45, 14.98, 0, 1, Easing.linear);
82|
83|  /* ring geometry */
84|  const circ = 2 * Math.PI * R;
85|  const ringDraw = ip(t, 3.15, 4.25, 0, 1, EIO);
86|  const prog = t < 5.0 ? 0 : ang / 360;
