107|  const labOff = (i: number) => {
108|    const [x, y] = pt(stationAng[i], R + (P ? 34 : 44) * u);
109|    return [x, y];
110|  };
111|
112|  const chrome = ip(t, 0.15, 0.7, 0, 1) * finalFade;
113|  const headSize = (P ? 92 : 112) * u;
114|
115|  return (
116|    <AbsoluteFill style={{ background: C.bg, fontFamily: C.sans, color: C.ink, overflow: "hidden" }}>
117|      {/* atmosphere: soft field + vignette */}
118|      <AbsoluteFill style={{
119|        background: `radial-gradient(${900 * u}px ${700 * u}px at ${cx}px ${cy}px, rgba(108,199,154,${0.07 * win(t, 3.4, 12.9, 1, 0.6)}), transparent 70%)`,
120|      }} />
