122|
123|      <AbsoluteFill style={{ transform: `scale(${push})`, opacity: finalFade }}>
124|        {/* ═════ 01 · THE PROBLEM ═════ */}
125|        {t < 4.4 && TASKS.map((txt, i) => {
126|          const at = 0.15 + i * 0.22;
127|          const pop = ip(t, at, at + 0.5, 0, 1, Easing.bezier(0.3, 1.6, 0.4, 1));
