157|            <Rise t={t} at={0.55} out={2.8} style={{ fontFamily: C.mono, fontSize: 23 * u, letterSpacing: ".14em", color: C.amber, marginBottom: 26 * u }}>
158|              4 SMALL JOBS · ALL WAITING ON SOMEONE
159|            </Rise>
160|            <div style={{ fontSize: headSize, fontWeight: 500, letterSpacing: "-.035em", lineHeight: 1.0 }}>
161|              <Rise t={t} at={0.8} out={2.85}>Your people have</Rise>
162|              <Rise t={t} at={0.98} out={2.92}><span style={{ color: C.ink2 }}>better work to do.</span></Rise>
163|            </div>
164|          </div>
165|        )}
166|
167|        {/* ═════ 02–04 · THE WHEEL ═════ */}
168|        <AbsoluteFill style={{
169|          transformOrigin: `${cx}px ${cy}px`, transform: `translate(${gdx}px, ${gdy}px) scale(${gScale})`,
170|          opacity: gOut,
171|        }}>
172|          <svg width={W} height={H} style={{ position: "absolute", inset: 0 }}>
173|            <defs>
174|              <linearGradient id="sw" x1="0" y1="0" x2="1" y2="0">
175|                <stop offset="0" stopColor="#fff" stopOpacity="0" /><stop offset=".5" stopColor="#fff" stopOpacity=".9" /><stop offset="1" stopColor="#fff" stopOpacity="0" />
176|              </linearGradient>
177|              <mask id="swm"><rect x={cx - R - 60 + sweep * (2 * R + 120) - 90} y={0} width={180} height={H} fill="url(#sw)" transform={`rotate(18 ${cx} ${cy})`} /></mask>
178|              <filter id="glow" x="-50%" y="-50%" width="200%" height="200%"><feGaussianBlur stdDeviation={10 * u} /></filter>
179|            </defs>
180|            {/* base ring, drawn clockwise from 12 o'clock */}
181|            <circle cx={cx} cy={cy} r={R} fill="none" stroke={C.line} strokeWidth={3 * u}
182|              strokeDasharray={`${circ * ringDraw} ${circ}`} transform={`rotate(-90 ${cx} ${cy})`} opacity={ringOn} />
183|            <circle cx={cx} cy={cy} r={R} fill="none" stroke={C.ink} strokeWidth={3 * u} mask="url(#swm)" opacity={0.85 * ringOn} />
