JS = r"""
(() => {
  const W = window, D = document;
  const vp = { w: W.innerWidth, h: W.innerHeight, dpr: W.devicePixelRatio };

  // ---- font sizes: every text-bearing element's computed font-size ----
  const small14 = [], small16 = [];
  D.querySelectorAll('body *').forEach(e => {
    if (!e.childNodes.length) return;
