  });
  const imgBytes = res.filter(r=>/\.(jpe?g|png|webp|mp4?|webm|gif)/.test(r.name));
  const totalBytes = res.reduce((a,r)=>a+r.init,0);
  const videoBytes = res.filter(r=>/\.mp4?$/.test(r.name));

  // ---- film / video specifics ----
  const v = D.querySelector('#film video, video');
  let film = null;
  if (v) {
    const vr = v.getBoundingClientRect();
    film = {
      paused: v.paused,
      autoplay: v.getAttribute('autoplay')!==null,
      hasPoster: !!v.getAttribute('poster'),
      poster: v.getAttribute('poster'),
      src: v.currentSrc || v.src,
      readyState: v.readyState,
      displayRect: { w: Math.round(vr.width), h: Math.round(vr.height), top: Math.round(vr.top), left: Math.round(vr.left) },
    };
  }
