  let pauseBtn = null;
  if (tog) {
    const r = tog.getBoundingClientRect();
    pauseBtn = { w: Math.round(r.width), h: Math.round(r.height), top: Math.round(r.top), left: Math.round(r.left), inView: r.top >= 0 && r.bottom <= W.innerHeight, visible: !!(getComputedStyle(tog).opacity && parseFloat(getComputedStyle(tog).opacity) > 0.01) };
  }

  return {
    vp, page: location.pathname+location.search, title: D.title,
    small14, small16, smallTap, overflow: { hasOverflow: over, scrollWidth: scrollW, innerW: innerW, maxRight: Math.round(maxRight), overflowPct, clippedSample: clipped },
    contrast: sampled, nav: navRect, fold: { firstCta, foldEls, visibleText: visFirst }, cls,
    resources: { imgBytes, videoBytes, totalBytes },
    film,
  };
})()
